#!/usr/bin/env python3
"""Deck expansion data (batch 3): Movie/TV, Music, Kids, Sports and Knowledge decks.

Each deck listed here gets exactly 40 brand-new cards so the deck reaches 60 total.
"""

LOCALES = [
    "en", "tr", "de", "ar", "be", "ca", "cs", "da", "el", "es",
    "fi", "fil", "fr", "hr", "id", "it", "ms", "nb", "nl", "pl",
    "pt", "ro", "ru", "sv", "uk",
]


def card(key, difficulty, translations):
    assert set(translations.keys()) == set(LOCALES), f"{key}: missing locales"
    return {"k": key, "d": difficulty, "t": {loc: translations[loc] for loc in LOCALES}}


def t(en, tr, de, ar, be, ca, cs, da, el, es, fi, fil, fr, hr, id_, it, ms, nb, nl, pl, pt, ro, ru, sv, uk):
    return dict(zip(LOCALES, [en, tr, de, ar, be, ca, cs, da, el, es, fi, fil, fr, hr, id_, it, ms, nb, nl, pl, pt, ro, ru, sv, uk]))


def sc(name, **overrides):
    """Proper noun kept as-is worldwide, with per-locale script overrides (ar/be/el/ru/uk...)."""
    values = {loc: name for loc in LOCALES}
    for loc, value in overrides.items():
        assert loc in values, f"{name}: unknown locale {loc}"
        values[loc] = value
    return values


